import{f as r,D as i,c as s,o,k as a,H as d,aq as l,a as n}from"./chunks/framework.dhdMY27E.js";const v=JSON.parse('{"title":"Geringe Anzahl an Renovate PRs zur gleichen Zeit","description":"","frontmatter":{},"headers":[],"relativePath":"technik/adr/adr-lower-number-of-renovate-prs.md","filePath":"technik/adr/adr-lower-number-of-renovate-prs.md"}'),h={name:"technik/adr/adr-lower-number-of-renovate-prs.md"};function u(c,e,g,p,f,m){const t=i("adr-status");return o(),s("div",null,[e[0]||(e[0]=a("h1",{id:"geringe-anzahl-an-renovate-prs-zur-gleichen-zeit",tabindex:"-1"},[n("Geringe Anzahl an Renovate PRs zur gleichen Zeit "),a("a",{class:"header-anchor",href:"#geringe-anzahl-an-renovate-prs-zur-gleichen-zeit","aria-label":'Permalink to "Geringe Anzahl an Renovate PRs zur gleichen Zeit"'},"​")],-1)),e[1]||(e[1]=a("h2",{id:"status",tabindex:"-1"},[n("Status "),a("a",{class:"header-anchor",href:"#status","aria-label":'Permalink to "Status"'},"​")],-1)),d(t,{status:"accepted"}),e[2]||(e[2]=l('<h2 id="kontext" tabindex="-1">Kontext <a class="header-anchor" href="#kontext" aria-label="Permalink to &quot;Kontext&quot;">​</a></h2><p>Aktuell achtet Renovate darauf, dass maximal 10 PRs zur selben Zeit offen sind. Wir haben die Regel aktiv dass ein Branch aktuell sein muss bevor er gemergt werden darf. Die PRs von Renovate werden aktuell gehalten. Wurde ein andere PR gemergt erfolgt ein Update des Branches via Force-Update. Für jeden neuen Push auf einen offenen PR werden die entsprechenden Actions ausgeführt. Mit unseren gut 12 Backend-Microservices führt ein PR zu 12 Jobs. Mit dem Standardlimit von 10 Renovate-PRs kann dies bis zu 120 parallele Jobs führen. Diese werden aber nicht gleichzeit abgearbeitet, ein Teil wird gequeued. 9 der 10 Jobs werden aber nicht direkt in einem Merge münden.</p><p>Das ganze führt dazu, dass man relativ lange warten muss um die Renovate-PRs abarbeiten zu können.</p><h2 id="entscheidung" tabindex="-1">Entscheidung <a class="header-anchor" href="#entscheidung" aria-label="Permalink to &quot;Entscheidung&quot;">​</a></h2><p>Die Menge an gleichzeiten Renovate-PRs werden auf 2 limitiert.</p><h2 id="konsequenzen" tabindex="-1">Konsequenzen <a class="header-anchor" href="#konsequenzen" aria-label="Permalink to &quot;Konsequenzen&quot;">​</a></h2><p>Renovate-PRs aus dem Bereich Security sind davon <a href="https://docs.renovatebot.com/configuration-options/#prconcurrentlimit" target="_blank" rel="noreferrer">nicht betroffen</a>.</p><h3 id="positiv" tabindex="-1">positiv <a class="header-anchor" href="#positiv" aria-label="Permalink to &quot;positiv&quot;">​</a></h3><p>Die einzelnen PRs können schneller bearbeitet werden.</p><h3 id="negativ" tabindex="-1">negativ <a class="header-anchor" href="#negativ" aria-label="Permalink to &quot;negativ&quot;">​</a></h3><p>Renovate-PRs die sich gegenseitig bedingen, und daher im Build fehlschlagen, sind schwerer zu erkennen.</p>',11))])}const k=r(h,[["render",u]]);export{v as __pageData,k as default};
